from pathlib import Path
from datetime import datetime, timezone
import json, hashlib
root=Path(__file__).resolve().parent.parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
screens=[('tron-active','active_tron','Tron demo with four visual achievements derived from three synthetic historical fixtures.'),('tron-mobile','mobile','Same Tron demo on390x844.'),('tron-launcher','launcher_or_progression','Tron selection and four deterministic achievement requirements, fulfilled by fixtures.'),('tron-new-player','launcher_or_progression','Tron launcher with empty history and locked requirements.'),('tron-tunnel','active_tron','Tron after100 accelerated work seconds; no saved history.'),('tron-core','active_tron','Tron after180 accelerated work seconds; no saved history.'),('tron-award','active_tron','Tron after320 accelerated work seconds; temporary demo precision preview, not permanent unlock.'),('neon-active','active_other','Neon expedition with route-choice UI in demo.'),('sky-active','active_other','Skybound expedition with route-choice UI in demo.'),('analysis-overview','result_or_analysis','Measured execution UI from synthetic fixture:30min ridden,10min skipped,24min remaining,10sec missing samples.'),('analysis-intervals','result_or_analysis','Per-block observed/planned seconds, power and adherence for the same fixture.'),('analysis-comparison','result_or_analysis','Power records, estimate/comparison context and training insights for synthetic fixture.')]
